    if(!service_facts(service_factsValue)) {
      testFailures = testFailures :+ st"'service_facts' did not match expected: value of the outgoing data port is ${service_factsValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


